using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
using LocalConverter;

static class VideoChecks
{
    static int count;static void Check(bool value,string name){if(!value)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
    static T Field<T>(object value,string name){return (T)value.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(value);}
    static object Call(object value,string name,params object[] args){SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());return value.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(value,args);}
    static void Until(Func<bool> ready){var clock=System.Diagnostics.Stopwatch.StartNew();while(!ready()){Application.DoEvents();Thread.Sleep(8);if(clock.Elapsed.TotalSeconds>90)throw new Exception("video test timeout");}}
    static void Wait(VideoWorkspace workspace){var task=Field<Task>(workspace,"operation");Until(()=>task.IsCompleted);task.GetAwaiter().GetResult();Application.DoEvents();}
    static void Shot(Form form,string path){Application.DoEvents();using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,form.Size));bitmap.Save(path);}}
    [STAThread]static int Main(string[] args)
    {
        try
        {
            Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var token=CancellationToken.None;
            var store=new EngineStore(Path.Combine(root,"外置引擎测试"));if(!store.Installed(VideoCatalog.Runtime))store.InstallArchive(VideoCatalog.Runtime,Path.GetFullPath(args[1]),token,s=>Console.WriteLine(s));var engine=new VideoEngine(store);Check(engine.Ready,"fixed official ZIP installs with a matching receipt");engine.Verify(token);Check(true,"all installed engine files pass integrity validation");
            string input=Path.Combine(root,"中文 视频样例.mp4"),outputs=Path.Combine(root,"outputs");Directory.CreateDirectory(outputs);string ffmpeg=engine.Executable("ffmpeg.exe");VideoEngine.Run(ffmpeg,"-hide_banner -loglevel error -nostdin -f lavfi -i testsrc2=size=320x180:rate=12 -f lavfi -i sine=frequency=440:sample_rate=44100 -t 2.5 -c:v libx264 -pix_fmt yuv420p -c:a aac -y "+SpeechProcess.Quote(input),token);string original=EngineStore.Hash(input,token);var info=engine.Inspect(input,token);Check(info.Width==320&&info.Height==180&&info.Audio&&Math.Abs(info.Duration-2.5)<.2,"Chinese path input reports video dimensions duration and audio");
            string frame=engine.Frame(info,1,root,token);using(var image=Image.FromFile(frame))Check(image.Width<=960&&image.Height<=540,"timeline preview is bounded and decodes a real frame");File.Delete(frame);
            for(int f=0;f<6;f++){var options=new VideoOptions{Format=f,MaxEdge=160};var output=engine.ConvertFile(info,outputs,options,token,p=>{});var converted=engine.Inspect(output,token);Check(converted.Width<=160&&converted.Height<=160&&converted.Audio&&converted.Duration>2,"output "+options.Extension+" is a playable resized video with sound");Check(Path.GetExtension(output)==options.Extension,"output "+options.Extension+" uses its actual requested container");string back=engine.ConvertFile(converted,Path.Combine(outputs,"reverse"),new VideoOptions(),token,null);var restored=engine.Inspect(back,token);Check(restored.Audio&&restored.Duration>2,"input "+options.Extension+" can also be decoded and converted back to MP4");}
            var silent=engine.ConvertFile(info,outputs,new VideoOptions{KeepAudio=false},token,null);Check(!engine.Inspect(silent,token).Audio,"unchecking sound creates a video without audio");
            string rotated=Path.Combine(root,"rotated.mov");VideoEngine.Run(ffmpeg,"-hide_banner -loglevel error -display_rotation 90 -i "+SpeechProcess.Quote(input)+" -c copy -y "+SpeechProcess.Quote(rotated),token);var rotatedInfo=engine.Inspect(rotated,token);Check(rotatedInfo.Width==180&&rotatedInfo.Height==320,"phone rotation metadata is reflected in displayed dimensions");string rotatedOutput=engine.ConvertFile(rotatedInfo,outputs,new VideoOptions(),token,null);var rotatedResult=engine.Inspect(rotatedOutput,token);Check(rotatedResult.Width==180&&rotatedResult.Height==320,"conversion preserves the visible portrait orientation");
            var gifOptions=new VideoOptions{Gif=true,Start=.5,End=1.7,GifWidth=160,Fps=10};string gif=engine.ConvertFile(info,outputs,gifOptions,token,null);using(var image=Image.FromFile(gif)){Check(image.Width<=160&&image.Height<=1280,"GIF export applies its selected dimensions");Check(image.GetFrameCount(FrameDimension.Time)>1,"GIF export contains multiple animated frames");}var gifInfo=engine.Inspect(gif,token);Check(!gifInfo.Audio&&Math.Abs(gifInfo.Duration-1.2)<.25,"GIF contains only the requested silent time range");Check(!Directory.GetFiles(outputs,"*.tmp").Any(),"completed operations leave no temporary palette or partial output");
            string colors=Path.Combine(root,"red-blue.mp4");VideoEngine.Run(ffmpeg,"-hide_banner -loglevel error -f lavfi -i color=c=red:s=160x90:r=10:d=1 -f lavfi -i color=c=blue:s=160x90:r=10:d=1 -filter_complex \"[0:v][1:v]concat=n=2:v=1:a=0\" -c:v libx264 -pix_fmt yuv420p -y "+SpeechProcess.Quote(colors),token);string blue=engine.ConvertFile(engine.Inspect(colors,token),outputs,new VideoOptions{Gif=true,Start=1.2,End=1.8,GifWidth=160,Fps=10},token,null);using(var image=new Bitmap(blue)){var pixel=image.GetPixel(80,45);Check(pixel.B>180&&pixel.R<70,"GIF time selection actually begins in the requested second color segment");}
            bool rejected=false;try{engine.ConvertFile(info,outputs,new VideoOptions{Gif=true,Start=2,End=1},token,null);}catch(IOException){rejected=true;}Check(rejected,"reversed GIF time ranges fail before conversion");rejected=false;try{engine.ConvertFile(info,outputs,new VideoOptions{Gif=true,End=4},token,null);}catch(IOException){rejected=true;}Check(rejected,"GIF time ranges outside the original duration are rejected");
            using(var cancel=new CancellationTokenSource()){cancel.CancelAfter(250);var watch=System.Diagnostics.Stopwatch.StartNew();bool cancelled=false;try{VideoEngine.Run(ffmpeg,"-hide_banner -loglevel error -re -f lavfi -i color=size=64x64 -f null -",cancel.Token);}catch(OperationCanceledException){cancelled=true;}Check(cancelled&&watch.Elapsed.TotalSeconds<5,"cancellation ends its own video process promptly");}
            string changed=Path.Combine(root,"changed.mp4");File.Copy(input,changed,true);var changedInfo=engine.Inspect(changed,token);File.SetLastWriteTimeUtc(changed,DateTime.UtcNow.AddMinutes(1));rejected=false;try{engine.ConvertFile(changedInfo,outputs,new VideoOptions(),token,null);}catch(IOException){rejected=true;}Check(rejected,"a changed original is rejected rather than using stale metadata");Check(EngineStore.Hash(input,token)==original,"all conversions leave the original bytes unchanged");
            using(var manager=new EngineDownloadManager(store))using(var form=new Form{ClientSize=new Size(900,660),Font=new Font("Microsoft YaHei UI",9.5F)})using(var workspace=new VideoWorkspace(store,manager))
            {
                form.Controls.Add(workspace);form.Show();Application.DoEvents();Call(workspace,"QueueAdd",(object)new[]{input});Wait(workspace);Until(()=>Field<Task>(workspace,"frameTask").IsCompleted);var start=Field<ModernButton>(workspace,"start");Check(start.Enabled&&Field<PictureBox>(workspace,"picture").Image!=null,"imported video enables conversion and shows a real preview");Check(Field<Label>(workspace,"positionLabel").Text.EndsWith("00:00:02.5"),"timeline duration is correct even before the slider is moved");Call(workspace,"SetMode",true);Check(!Field<ModernButton>(workspace,"download").Visible,"new GIF mode never exposes the conversion download result");Field<NumericUpDown>(workspace,"startTime").Value=.5M;Field<NumericUpDown>(workspace,"endTime").Value=1.7M;Field<ModernButton>(workspace,"previewGif").PerformClick();Wait(workspace);Check(Field<Label>(workspace,"previewTitle").Text.Contains("GIF 效果预览")&&Field<PictureBox>(workspace,"picture").Image.GetFrameCount(FrameDimension.Time)>1,"GIF preview uses the actual selected rendering settings");Shot(form,Path.Combine(root,"video-gif-preview.png"));
                start.PerformClick();Wait(workspace);var results=Field<ToolResultStore>(workspace,"outcomes");Check(results.Get("视频转 GIF").Files.Length==1&&Field<ModernButton>(workspace,"download").Visible,"GIF generation exposes only completed downloadable results");Field<ComboBox>(workspace,"fps").SelectedIndex=2;Check(Field<ModernButton>(workspace,"download").Text.Contains("上次"),"changed GIF parameters explicitly label previous results");Call(workspace,"SetMode",false);Check(!Field<ModernButton>(workspace,"download").Visible,"conversion tab does not reuse GIF download results");Call(workspace,"SetMode",true);Check(Field<ModernButton>(workspace,"download").Visible,"returning to GIF restores its own result");
                Call(workspace,"SetMode",false);start.PerformClick();Wait(workspace);Check(results.Get("格式转换").Files.Length==1,"conversion owns a separate completed result alongside GIF");Call(workspace,"SetMode",true);Field<NumericUpDown>(workspace,"endTime").Value=1.6M;Call(workspace,"SetMode",false);Check(!Field<ModernButton>(workspace,"download").Text.Contains("上次"),"changing GIF-only options does not invalidate an unchanged video conversion");results.Get("格式转换").Downloaded=results.Get("视频转 GIF").Downloaded=true;var stop=workspace.StopAsync();Until(()=>stop.IsCompleted);stop.GetAwaiter().GetResult();form.Close();
            }
            using(var main=new MainForm(new string[0]))
            {
                main.Show();Application.DoEvents();main.Size=main.MinimumSize;Call(main,"ChangeWorkspace",3);var workspace=Field<VideoWorkspace>(main,"videoWorkspace");Check(workspace.Visible&&Field<ModernButton>(main,"videoSection").Primary,"video section is integrated into the main sidebar");if(!new VideoEngine(Field<AudioWorkspace>(main,"audioWorkspace").ExternalEngines).Ready)Check(!Field<ModernButton>(workspace,"start").Enabled&&!Field<ModernButton>(workspace,"add").Enabled,"absent video engine leaves the interface visible with processing disabled");
                foreach(bool mode in new[]{false,true}){Call(workspace,"SetMode",mode);Application.DoEvents();var options=Field<TableLayoutPanel>(workspace,"optionRows");Check(options.Controls.Cast<Control>().All(c=>c.Right<=options.ClientSize.Width&&c.Bottom<=options.ClientSize.Height),"all "+(mode?"GIF":"conversion")+" settings fit the minimum window");Shot(main,Path.Combine(root,mode?"video-gif-minimum.png":"video-convert-minimum.png"));}
                var sections=new[]{Field<ModernButton>(main,"pdfSection"),Field<ModernButton>(main,"audioSection"),Field<ModernButton>(main,"imageSection"),Field<ModernButton>(main,"videoSection")};Check(sections.Select(s=>s.Size).Distinct().Count()==1,"all four sidebar categories have matching dimensions");Check(Field<DownloadTasksButton>(main,"engineDownloadsButton").Visible,"the shared global download icon remains available in video tools");main.Close();Until(()=>main.IsDisposed);
            }
            using(var manager=new EngineDownloadManager(store))using(var form=new Form{ClientSize=new Size(900,660)})using(var workspace=new VideoWorkspace(store,manager)){form.Controls.Add(workspace);form.Scale(new SizeF(1.5F,1.5F));workspace.SetLayoutScale(1.5F);form.Show();Application.DoEvents();Call(workspace,"SetMode",true);var rows=Field<TableLayoutPanel>(workspace,"optionRows");Check(rows.RowStyles[0].Height==45&&rows.ColumnStyles[0].Width==141&&TextRenderer.MeasureText(rows.Controls[0].Text,rows.Controls[0].Font).Width<=rows.Controls[0].ClientSize.Width,"scaled GIF rows and caption columns fit the complete time labels");Check(rows.Controls.Cast<Control>().All(c=>c.Right<=rows.ClientSize.Width&&c.Bottom<=rows.ClientSize.Height),"scaled GIF controls stay inside the settings panel");Shot(form,Path.Combine(root,"video-gif-150-percent.png"));form.Close();}
            Console.WriteLine("ALL "+count+" VIDEO CHECKS PASSED");return 0;
        }catch(Exception error){Console.Error.WriteLine(error);return 1;}
    }
}
